-- ---------------------------------------------------------------------------
-- Automatic monthly joining fee waivers (see docs/fee-waiver-rules.md).
--
-- Additive only: one enum, two tables, new nullable / defaulted columns, two
-- narrow backfills. No existing column, row value or constraint is changed
-- except the two backfilled columns introduced here.
--
-- Parts marked MANUAL are not generated by Prisma (CHECK constraints, the
-- partial unique index, the settings row and the backfills). Prisma 5.22
-- cannot express partial indexes, so a later `prisma migrate dev` may report
-- the index as drift: never accept a generated DROP INDEX for it. Guarded by
-- tests/fee-waiver/fee-waiver-migration-guard.test.cjs.
-- ---------------------------------------------------------------------------

-- CreateEnum
CREATE TYPE "FeeWaiverType" AS ENUM ('PERCENTAGE', 'FIXED_AMOUNT');

-- AlterTable
ALTER TABLE "Student" ADD COLUMN     "approvedAt" TIMESTAMP(3);

-- AlterTable
ALTER TABLE "ClassStudentFee" ADD COLUMN     "joinWaiverBaseAmount" INTEGER,
ADD COLUMN     "joinWaiverComputedAt" TIMESTAMP(3),
ADD COLUMN     "joinWaiverEnrolledAt" TIMESTAMP(3),
ADD COLUMN     "joinWaiverLecturesBefore" INTEGER,
ADD COLUMN     "joinWaiverRuleId" TEXT,
ADD COLUMN     "joinWaiverSequence" INTEGER,
ADD COLUMN     "joinWaiverType" "FeeWaiverType",
ADD COLUMN     "joinWaiverValue" INTEGER,
ADD COLUMN     "lateJoinDeductManual" BOOLEAN NOT NULL DEFAULT false;

-- CreateTable
CREATE TABLE "ClassFeeWaiverRule" (
    "id" TEXT NOT NULL,
    "classId" TEXT NOT NULL,
    "sequence" INTEGER NOT NULL,
    "type" "FeeWaiverType" NOT NULL,
    "value" INTEGER NOT NULL,
    "status" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ClassFeeWaiverRule_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "FeeWaiverSettings" (
    "id" TEXT NOT NULL DEFAULT 'default',
    "startYear" INTEGER NOT NULL,
    "startMonth" INTEGER NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "FeeWaiverSettings_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "ClassFeeWaiverRule_classId_status_sequence_idx" ON "ClassFeeWaiverRule"("classId", "status", "sequence");

-- AddForeignKey
ALTER TABLE "ClassStudentFee" ADD CONSTRAINT "ClassStudentFee_joinWaiverRuleId_fkey" FOREIGN KEY ("joinWaiverRuleId") REFERENCES "ClassFeeWaiverRule"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ClassFeeWaiverRule" ADD CONSTRAINT "ClassFeeWaiverRule_classId_fkey" FOREIGN KEY ("classId") REFERENCES "Class"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- MANUAL: value / sequence / settings bounds (the services validate too).
ALTER TABLE "ClassFeeWaiverRule" ADD CONSTRAINT "ClassFeeWaiverRule_value_check" CHECK ("value" > 0);
ALTER TABLE "ClassFeeWaiverRule" ADD CONSTRAINT "ClassFeeWaiverRule_sequence_check" CHECK ("sequence" BETWEEN 1 AND 20);
ALTER TABLE "ClassFeeWaiverRule" ADD CONSTRAINT "ClassFeeWaiverRule_percentage_check" CHECK ("type" <> 'PERCENTAGE' OR "value" <= 100);
ALTER TABLE "FeeWaiverSettings" ADD CONSTRAINT "FeeWaiverSettings_startMonth_check" CHECK ("startMonth" BETWEEN 1 AND 12);
ALTER TABLE "FeeWaiverSettings" ADD CONSTRAINT "FeeWaiverSettings_startYear_check" CHECK ("startYear" BETWEEN 2026 AND 2100);

-- MANUAL: one ACTIVE rule per (class, sequence). Removed rules (status 1)
-- are outside the index, so a removed position can be reused.
CREATE UNIQUE INDEX "ClassFeeWaiverRule_active_sequence_key"
  ON "ClassFeeWaiverRule" ("classId", "sequence")
  WHERE "status" = 0;

-- MANUAL: launch gate. The first full Asia/Colombo calendar month after this
-- migration is applied (i.e. after deployment). now() is an absolute instant,
-- so the result does not depend on the server or session timezone.
-- Applied on 2026-11-15 -> 2026-12; applied at 2026-12-01 00:30 Colombo -> 2027-01.
INSERT INTO "FeeWaiverSettings" ("id", "startYear", "startMonth")
SELECT 'default', EXTRACT(YEAR FROM m)::int, EXTRACT(MONTH FROM m)::int
FROM (SELECT date_trunc('month', now() AT TIME ZONE 'Asia/Colombo') + interval '1 month' AS m) AS launch;

-- MANUAL backfill 1: every existing positive late-join deduction was entered
-- by a teacher; mark it manual so automatic calculation never overwrites it.
UPDATE "ClassStudentFee" SET "lateJoinDeductManual" = true WHERE "lateJoinDeduct" > 0;

-- MANUAL backfill 2 (approximate, documented): already-approved public
-- registrations get approvedAt = confirmedAt. confirmedAt holds the LATEST
-- decision, so a decline -> re-approval history cannot be recovered; all such
-- values predate the launch month and therefore never decide a waiver.
UPDATE "Student" SET "approvedAt" = "confirmedAt"
WHERE "registrationSource" = 'PUBLIC_CLASS'
  AND "confirmationStatus" = 'APPROVED'
  AND "confirmedAt" IS NOT NULL;
